//! Shapes of the CLI's `--json` output and their JSON Schemas.
//!
//! Every JSON document printed by `evidence --json <command>` is an envelope
//! `{"version": 1, "<key>": <payload>}`. The schemas of these envelopes are published in
//! `schemas/output/` (generated by `cargo xtask schemas`) and are part of the public contract.

use serde::Serialize;

use crate::status::{PairStatus, status};
use crate::workspace::{Pair, Workspace};

/// Version of the `--json` output shapes.
pub const JSON_VERSION: u32 = 1;

/// Prefix of the published schema `$id`s.
const SCHEMA_URL_PREFIX: &str = "https://evidence-cli.github.io/schemas/output/";

/// `evidence show`: one pair with its definition, status, and neighbors.
#[derive(Debug, Clone, Serialize, schemars::JsonSchema)]
pub struct PairView {
    /// Evidence id.
    pub id: String,
    /// Evidence file, relative to the project root.
    pub evid: String,
    /// Subject, relative to the project root.
    pub subject: String,
    /// The parsed evidence file (definition and state).
    pub definition: crate::format::EvidenceFile,
    /// Freshness.
    pub status: PairStatus,
    /// Set for a member of a list: its parent and key.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub membership: Option<crate::workspace::Membership>,
    /// Direct dependencies (ids).
    pub dependencies: Vec<String>,
    /// Direct dependents (ids).
    pub dependents: Vec<String>,
}

impl PairView {
    /// Builds the view of `pair`.
    pub(crate) fn new(ws: &Workspace, pair: &Pair, now: jiff::Timestamp) -> Self {
        Self {
            id: pair.id.clone(),
            evid: pair.evid_rel.clone(),
            subject: pair.subject_rel.clone(),
            definition: pair.file.clone(),
            status: status(ws, pair, now),
            membership: pair.membership.clone(),
            dependencies: ws
                .dependencies(&pair.id)
                .iter()
                .map(|p| p.id.clone())
                .collect(),
            dependents: ws
                .dependents(&pair.id)
                .iter()
                .map(|p| p.id.clone())
                .collect(),
        }
    }
}

/// `(file name, commands, envelope key, payload type)` of every published output shape.
macro_rules! shapes {
    ($($file:literal, $commands:literal, $key:literal => $ty:ty;)*) => {
        /// Envelope schemas of every `--json` output, as `(file name under schemas/, schema)`.
        pub fn output_schemas() -> Vec<(&'static str, serde_json::Value)> {
            vec![$((concat!("output/", $file), envelope::<$ty>($file, $commands, $key)),)*]
        }
    };
}

shapes! {
    "update.schema.json", "update", "update" => crate::update::UpdateReport;
    "status.schema.json", "status", "status" => Vec<PairStatus>;
    "outdated.schema.json", "outdated", "outdated" => Vec<PairStatus>;
    "why.schema.json", "why", "status" => PairStatus;
    "pair.schema.json", "show", "pair" => PairView;
    "coverage.schema.json", "coverage", "coverage" => crate::coverage::CoverageReport;
    "tree.schema.json", "tree", "tree" => Vec<crate::graph::TreeNode>;
    "search.schema.json", "search", "hits" => Vec<crate::search::Hit>;
    "history.schema.json", "history", "history" => Vec<crate::history::Event>;
    "validate.schema.json", "validate", "diagnostics" => Vec<crate::format::Diagnostic>;
    "review.schema.json", "review", "review" => Vec<crate::review::Pinned>;
    "remove.schema.json", "remove", "removed" => crate::remove::Removed;
    "cat.schema.json", "cat (directory snapshots)", "tree" => Vec<crate::project::DirEntry>;
    "store-verify.schema.json", "store verify", "verify" => crate::project::StoreCheck;
    "store-prune.schema.json", "store prune", "prune" => crate::project::Pruned;
    "index.schema.json", "index rebuild, index sync", "index" => crate::project::IndexStats;
}

fn envelope<T: schemars::JsonSchema>(file: &str, commands: &str, key: &str) -> serde_json::Value {
    let mut generator = schemars::generate::SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator();
    let mut payload = generator.root_schema_for::<T>().to_value();
    let defs = payload
        .as_object_mut()
        .and_then(|m| {
            m.remove("$schema");
            m.remove("title");
            m.remove("$defs")
        })
        .unwrap_or_else(|| serde_json::json!({}));
    let mut schema = serde_json::json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": format!("{SCHEMA_URL_PREFIX}{file}"),
        "title": format!("evidence --json {commands}"),
        "type": "object",
        "required": ["version", key],
        "properties": {
            "version": { "const": JSON_VERSION },
            key: payload,
        },
    });
    if defs.as_object().is_some_and(|d| !d.is_empty())
        && let Some(map) = schema.as_object_mut()
    {
        map.insert("$defs".into(), defs);
    }
    schema
}
